from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from datetime import datetime

app = FastAPI()
todos = {}
next_id = 1

class TodoCreate(BaseModel):
    title: str
    priority: str = "medium"

@app.post("/todos", status_code=201)
async def create(todo: TodoCreate):
    global next_id
    todos[next_id] = {"id": next_id, "title": todo.title, "priority": todo.priority, "created_at": str(datetime.now())}
    next_id += 1
    return todos[next_id - 1]

@app.get("/todos")
async def get_all():
    return list(todos.values())

